      padding: /^\+\s/.test(text) ? `4px ${wide ? 10 : 8}px 4px ${(wide ? 10 : 8) + 3}px` : `4px ${wide ? 10 : 8}px`,
      border: `1px solid ${active ? activeBorder : "transparent"}`,
      "border-radius": CANVAS_BAR_BUTTON_RADIUS_PX,
