      opacity: disabled ? NOVAFLOW_DISABLED_OPACITY : "1",
      "font-size": "11px",
      "font-weight": NOVAFLOW_MEDIUM_FONT_WEIGHT,
      "line-height": "1",
      "box-sizing": "border-box"
