    const rawKind = getAiSequenceSourceOwnedUploadKind(dropzone);
    const rawKindInput = rawKind ? findAiSequenceNativeInputByRawKind(dropzone, rawKind) : null;
    if (rawKindInput instanceof HTMLInputElement) return rawKindInput;
    const bottomWorkspace = dropzone.closest('[data-novaflow-ai-bottom-workspace="1"]');
    const postSection = dropzone.closest('[data-novaflow-ai-post-section="1"]');
    const bottomZoneLabel = getAiSequenceBottomUploadZoneLabel(dropzone);
    if (isInsideNovaflowRuntimeIgnore(dropzone) && !bottomZoneLabel && !isAiSequenceSourceOwnedBottomUploadDropzone(dropzone)) return null;
    const primaryScope = bottomWorkspace instanceof HTMLElement
      ? bottomWorkspace
      : (postSection instanceof HTMLElement ? postSection : dropzone.parentElement);
    if (!(primaryScope instanceof HTMLElement)) return null;
    const scopes = [primaryScope];
    const globalBottomWorkspace = document.querySelector('[data-novaflow-ai-bottom-workspace="1"]');
    if (
      postSection instanceof HTMLElement &&
      globalBottomWorkspace instanceof HTMLElement &&
      !scopes.includes(globalBottomWorkspace)
    ) {
        scopes.push(globalBottomWorkspace);
    }
    scopes.forEach(ensureAiSequenceNativeUploadInputZones);
    const localInput = findAiSequenceLocalReferenceFileInput(dropzone, bottomZoneLabel);
    if (localInput instanceof HTMLInputElement) return localInput;
    const collectNativeInputs = (scope) => Array.from(scope.querySelectorAll('input[type="file"]'))
      .filter((input) => isAiSequenceUsableReferenceFileInput(input));
    const inputs = scopes.flatMap(collectNativeInputs)
      .filter((input, index, list) => list.indexOf(input) === index);
    const bottomInputs = globalBottomWorkspace instanceof HTMLElement
      ? collectNativeInputs(globalBottomWorkspace)
      : [];
    const documentInputs = bottomZoneLabel
      ? collectNativeInputs(document)
      : [];
    if (!inputs.length && !bottomInputs.length && !documentInputs.length) return null;
    const label = getAiAnimationDropzoneLabel(dropzone);
    const zonedInput = findAiSequenceUploadInputByZone(inputs, label) ||
      findAiSequenceUploadInputByZone(bottomInputs, label) ||
      findAiSequenceUploadInputByZone(documentInputs, label);
    if (zonedInput instanceof HTMLInputElement) return zonedInput;
    const fallbackInputs = Array.from(new Set(inputs.concat(bottomInputs, documentInputs)));
    const frameInputOffset = fallbackInputs.length >= 4 ? 2 : 1;
    if (label.includes("\u9996\u5e27")) return fallbackInputs[frameInputOffset] || fallbackInputs[1] || fallbackInputs[0] || null;
    if (label.includes("\u5c3e\u5e27")) return fallbackInputs[frameInputOffset + 1] || fallbackInputs[2] || fallbackInputs[1] || fallbackInputs[0] || null;
    if (label.includes("\u53c2\u8003\u56fe")) return fallbackInputs[0] || null;
    if (label.includes("\u4e0a\u4f20\u8272\u5f69\u6821\u6b63\u53c2\u7167")) return bottomInputs[1] || fallbackInputs[1] || bottomInputs[0] || fallbackInputs[0] || null;
    if (bottomZoneLabel) return fallbackInputs[0] || null;
