    if (!(workspace instanceof HTMLElement) || !(resourceHost instanceof HTMLElement) || !(bottomWorkspace instanceof HTMLElement) || !(mainStage instanceof HTMLElement)) return;
    const target = getAiAnimationCanvasTarget(mainStage);
