    if (
      target.transformTarget.getAttribute("data-novaflow-ai-entry-fit-guard") === "1" &&
      target.transformTarget.style.getPropertyValue("--novaflow-ai-entry-fit-scale")
    ) {
      return;
    }
    const workspaceRect = workspace.getBoundingClientRect();
    const resourceRect = resourceHost.getBoundingClientRect();
    const bottomRect = bottomWorkspace.getBoundingClientRect();
    const frameRect = target.stageFrame.getBoundingClientRect();
    const topGroup = findAiAnimationTopModeGroup(workspace);
    const topRect = topGroup instanceof HTMLElement ? topGroup.getBoundingClientRect() : null;
    const canvasWidth = parseFloat(target.canvas.style.width) || target.canvas.offsetWidth || 720;
    const canvasHeight = parseFloat(target.canvas.style.height) || target.canvas.offsetHeight || 1280;
    const safeLeft = Math.round(workspaceRect.left + AI_ANIMATION_PREVIEW_UI_GAP);
    const safeRight = Math.round(Math.max(safeLeft + 160, resourceRect.left - AI_ANIMATION_PREVIEW_UI_GAP));
    const topBaseline = topRect ? topRect.bottom + 18 : workspaceRect.top + 72;
