    const viewport = getAiSequencePreviewViewport(document);
    if (!(viewport instanceof HTMLElement) || isAiSequencePreviewControlEventTarget(event)) return false;
    if (!(getAiSequencePreviewMedia(viewport) instanceof HTMLElement)) return false;
