    backplate.style.setProperty("--novaflow-ai-media-scale", String(Math.round(state.scale * 10000) / 10000));
    backplate.style.setProperty("--novaflow-ai-media-pan-x", `${Math.round(state.panX)}px`);
    backplate.style.setProperty("--novaflow-ai-media-pan-y", `${Math.round(state.panY)}px`);
    backplate.style.setProperty("--novaflow-ai-media-center-x", `${Math.round(centerX)}px`);
