      canvas.style.setProperty("--novaflow-ai-media-natural-height", `${Math.max(1, Math.round(size.height))}px`);
      canvas.style.setProperty("--novaflow-ai-media-scale", String(Math.round(state.scale * 10000) / 10000));
      canvas.style.setProperty("--novaflow-ai-media-pan-x", `${Math.round(state.panX)}px`);
      canvas.style.setProperty("--novaflow-ai-media-pan-y", `${Math.round(state.panY)}px`);
      canvas.style.setProperty("--novaflow-ai-media-center-x", `${Math.round(centerX)}px`);
