        "top": "var(--novaflow-ai-media-center-y, 50%)",
        "right": "auto",
        "bottom": "auto",
        "margin": "0",
        "width": "var(--novaflow-ai-media-natural-width, auto)",
        "height": "var(--novaflow-ai-media-natural-height, auto)",
        "max-width": "none",
        "max-height": "none",
        "object-fit": "contain",
        "transform": "translate(-50%, -50%) translate(var(--novaflow-ai-media-pan-x, 0px), var(--novaflow-ai-media-pan-y, 0px)) scale(var(--novaflow-ai-media-scale, 1))",
        "transform-origin": "center center",
        "background": "transparent",
        "background-color": "transparent",
        "background-image": "none",
        "box-shadow": "none",
