    const initialAnimationTargetActive = Boolean(
      document.body?.classList.contains("novaflow-primary-target-animation")
    );
    if (!document.body || (!initialAnimationTargetActive && !initialTransactionPending)) {
      clearAiAnimationPrimaryEntryStableRefresh();
      return;
    }
