      rightPanel.style.setProperty("width", "100%", "important");
      rightPanel.style.setProperty("min-width", "0", "important");
      rightPanel.style.setProperty("max-width", "100%", "important");
      rightPanel.style.setProperty("height", "100%", "important");
      rightPanel.style.setProperty("min-height", "0", "important");
      rightPanel.style.setProperty("padding-bottom", "14px", "important");
      rightPanel.style.setProperty("border", "0", "important");
