    return Boolean(
      document.querySelector('[data-panel-id="bone-ai"]') ||
      document.querySelector('[data-novaflow-spine-split="1"], [data-psd-fusion-ui="1"]') ||
      document.body.getAttribute("data-novaflow-spine-split-workspace-active") === "1"
    );
