  function isRibbonParameterPresetButton(button) {
    if (!(button instanceof HTMLElement) || button.tagName !== "BUTTON") return false;
    if (!button.closest('[data-novaflow-ribbon-panel="1"], .nf-panel')) return false;
    const text = normalizeText(button.textContent || "");
    if (!RIBBON_PRESET_BUTTON_LABELS.has(text) && !RIBBON_LEGACY_PRESET_BUTTON_LABELS.has(text)) return false;
    if (button.closest('[data-novaflow-ribbon-preset-grid="1"]')) return true;
    const parent = button.parentElement;
    if (!(parent instanceof HTMLElement)) return false;
    const directButtons = Array.from(parent.children).filter((child) => (
      child instanceof HTMLElement &&
      child.tagName === "BUTTON" &&
      isVisible(child)
    ));
    return isRibbonPresetButtonGrid(directButtons);
  }

  function isRibbonWriteAnimationButton(button) {
    if (!(button instanceof HTMLElement) || button.tagName !== "BUTTON") return false;
    if (button.getAttribute("data-novaflow-ribbon-action-kind") === "write") return true;
    if (!button.closest('[data-novaflow-ribbon-panel="1"], .nf-panel')) return false;
    const text = normalizeText(button.textContent || "");
    return text.includes(normalizeText(RIBBON_WRITE_CURRENT_ANIMATION_TEXT)) || text === normalizeText(RIBBON_WRITE_ANIMATION_TEXT);
  }

  function isRibbonRestoreActionText(text) {
    const normalized = normalizeText(text || "");
    return normalized.includes(normalizeText(RIBBON_RESTORE_CURRENT_ANIMATION_TEXT)) ||
      normalized === normalizeText(RIBBON_RESTORE_ANIMATION_TEXT) ||
      normalized === normalizeText(RIBBON_RESTORE_LEGACY_TEXT);
  }

  function isRibbonRestoreAnimationButton(button) {
    if (!(button instanceof HTMLElement) || button.tagName !== "BUTTON") return false;
    if (button.getAttribute("data-novaflow-ribbon-action-kind") === "restore") return true;
    if (!button.closest('[data-novaflow-ribbon-panel="1"], .nf-panel')) return false;
    return isRibbonRestoreActionText(button.textContent || "");
  }

  function getRibbonParameterPresetOverride(button) {
    if (!isRibbonParameterPresetButton(button)) return null;
    const label = normalizeText(button.textContent || "");
    const preset = RIBBON_PARAMETER_PRESET_OVERRIDES.find((entry) => normalizeText(entry.label) === label);
    return preset?.values || null;
  }

  function getReactFiberFromElement(element) {
    if (!(element instanceof Element)) return null;
    let keys = [];
    try {
      keys = Object.getOwnPropertyNames(element);
    } catch (_) {
      keys = [];
    }
    const key = keys.find((name) =>
      name.startsWith("__reactFiber$") ||
      name.startsWith("__reactInternalInstance$") ||
      name.startsWith("__reactContainer$")
    );
    return key ? element[key] : null;
  }

  function hasRibbonProjectSetProps(props) {
    if (!props || typeof props !== "object") return false;
    if (typeof props.setProject !== "function") return false;
    const project = props.project && typeof props.project === "object" ? props.project : null;
    if (!project || !project.animations || typeof project.animations !== "object") return false;
    return "activeAnimationName" in props || "spineSubEditor" in props || "source" in props;
  }

  function walkRibbonReactFibers(callback, root = document) {
    if (typeof callback !== "function") return 0;
    const scope = root instanceof Document || root instanceof HTMLElement ? root : document;
    const focused = scope instanceof Document
      ? Array.from(scope.querySelectorAll('[data-novaflow-ribbon-panel="1"], [data-novaflow-skeleton-tree-list="1"], [data-preview-ui="1"], canvas'))
      : Array.from(scope.querySelectorAll('[data-novaflow-ribbon-panel="1"], [data-novaflow-skeleton-tree-list="1"], [data-preview-ui="1"], canvas'));
    const elements = Array.from(new Set([
      document.getElementById("root"),
      document.body,
      scope instanceof HTMLElement ? scope : null,
      ...focused
    ].filter(Boolean)));
    const visited = new Set();
    let visitedCount = 0;
    elements.forEach((element) => {
      const rootFiber = getReactFiberFromElement(element);
      if (!rootFiber) return;
      const stack = [rootFiber];
      while (stack.length) {
        const fiber = stack.pop();
        if (!fiber || visited.has(fiber)) continue;
        visited.add(fiber);
        visitedCount += 1;
        callback(fiber);
        if (fiber.return) stack.push(fiber.return);
        if (fiber.child) stack.push(fiber.child);
        if (fiber.sibling) stack.push(fiber.sibling);
      }
    });
    return visitedCount;
  }

  function guardRibbonProjectSetPropsFromFiber(fiber) {
    let guarded = false;
    [fiber?.memoizedProps, fiber?.pendingProps].forEach((props) => {
      if (hasRibbonProjectSetProps(props)) {
        guarded = guardRibbonProjectSetProjectCallback(props) || guarded;
      }
    });
    return guarded;
  }

  // A walk that found no ribbon project is remembered for 600 ms: with no
