  function getRibbonBoneParentName(bone) {
    const parent = bone?.parent;
    if (typeof parent === "string") return parent.trim();
    return String(parent?.name || parent?.data?.name || "").trim();
  }

  function buildRibbonChildMap(project) {
    const children = new Map();
    const bones = Array.isArray(project?.bones) ? project.bones : [];
    bones.forEach((bone) => {
      const name = getRibbonBoneName(bone);
      const parent = getRibbonBoneParentName(bone);
      if (!name || !parent || name === parent) return;
      if (!children.has(parent)) children.set(parent, []);
      children.get(parent).push(name);
    });
    return children;
  }

  function buildRibbonParentMap(project) {
    const parents = new Map();
    const bones = Array.isArray(project?.bones) ? project.bones : [];
    bones.forEach((bone) => {
      const name = getRibbonBoneName(bone);
      const parent = getRibbonBoneParentName(bone);
      if (!name || !parent || name === parent) return;
      parents.set(name, parent);
    });
    return parents;
  }

  function scoreRibbonElasticChild(parentBoneName, childBoneName) {
    const child = String(childBoneName || "").toLowerCase();
    const parent = String(parentBoneName || "").toLowerCase();
    let score = 0;
    if (/(hair|tail|cape|scarf|wing|ribbon|strap|pend|chain|feather|fx)/.test(child)) score += 16;
    if (/(tip|end|_b$|_c$|_d$|[0-9]+$)/.test(child)) score += 4;
    if (child.includes(parent)) score += 2;
    return score;
  }

  function buildRibbonElasticChain(project, rootBoneName, maxBones = 8) {
    return buildRibbonElasticChainEntries(project, rootBoneName, maxBones).map((entry) => entry.name);
  }

  function buildRibbonElasticChainEntries(project, rootBoneName, maxBones = 8) {
    const root = String(rootBoneName || "").trim();
    if (!root || root === "root") return [];
    const children = buildRibbonChildMap(project);
    const entries = [{ name: root, chainIndex: 0 }];
    const visited = new Set([root]);
    let current = root;
    for (let depth = 1; depth < maxBones; depth += 1) {
      const options = (children.get(current) || [])
        .map((name) => String(name || "").trim())
        .filter((name) => name && !visited.has(name));
      options.sort((a, b) => {
        const scoreDiff = scoreRibbonElasticChild(current, b) - scoreRibbonElasticChild(current, a);
        return scoreDiff || a.localeCompare(b);
      });
      const next = options[0];
      if (!next) break;
      visited.add(next);
      entries.push({ name: next, chainIndex: depth });
      current = next;
    }
    return entries;
  }

  function buildRibbonElasticPreviewChainEntries(project, rootBoneName, maxDepth = 8, maxTargets = 16) {
    const root = String(rootBoneName || "").trim();
    if (!root || root === "root") return [];
    const children = buildRibbonChildMap(project);
    const entries = [];
    const visited = new Set([root]);
    const queue = [{ name: root, depth: 0 }];
    while (queue.length && entries.length < maxTargets) {
      const current = queue.shift();
      if (!current || !current.name) continue;
      entries.push({ name: current.name, chainIndex: current.depth });
      if (entries.length >= maxTargets || current.depth >= maxDepth) continue;
      (children.get(current.name) || []).forEach((childName) => {
        const child = String(childName || "").trim();
        if (!child || visited.has(child)) return;
        visited.add(child);
        queue.push({ name: child, depth: current.depth + 1 });
      });
    }
    return entries;
  }

  function normalizeRibbonSelectedBoneNames(names) {
    return (Array.isArray(names) ? names : [])
      .map((name) => String(name || "").trim())
      .filter((name) => name && name !== "root")
      .filter((name, index, list) => list.indexOf(name) === index);
  }

  function getRibbonProjectBoneNames(project) {
    return (Array.isArray(project?.bones) ? project.bones : [])
      .map((bone) => getRibbonBoneName(bone))
      .filter((name) => name && name !== "root")
      .filter((name, index, list) => list.indexOf(name) === index)
      .sort((a, b) => b.length - a.length || a.localeCompare(b));
  }

  function matchRibbonBoneNameFromText(text, boneNames) {
    const source = normalizeText(text || "");
    if (!source) return "";
    if (source === "root" || source.includes("\u5f53\u524d\u5de5\u7a0broot")) return "";
    const names = Array.isArray(boneNames) ? boneNames : [];
    const exact = names.find((name) => source === normalizeText(name));
    if (exact) return exact;
    return names.find((name) => {
      const normalized = normalizeText(name);
      return normalized && normalized.length >= 2 && source.includes(normalized);
    }) || "";
  }

  function getRibbonDirectSelectedBoneNamesFromDom(project) {
    const boneNames = getRibbonProjectBoneNames(project);
    const selected = [];
    const addName = (name) => {
      const next = String(name || "").trim();
      if (next && next !== "root" && !selected.includes(next)) selected.push(next);
    };
    try {
      let nodes = Array.from(document.querySelectorAll(
        '[data-novaflow-skeleton-tree-list="1"] [data-novaflow-skeleton-bone-row="1"][data-novaflow-skeleton-sidebar-item-active="1"]'
      ));
      if (!nodes.length && boneNames.length) {
        nodes = Array.from(document.querySelectorAll('[data-novaflow-skeleton-tree-list="1"] div')).filter((node) => {
          if (!(node instanceof HTMLElement) || !isVisible(node)) return false;
          const rect = node.getBoundingClientRect();
          if (rect.height < 20 || rect.height > 36) return false;
          const style = window.getComputedStyle(node);
          if (style.display !== "flex" || style.cursor !== "pointer") return false;
          if (!hasNovaflowSkeletonActiveState(node, { includeComputedVisual: false })) return false;
          return !!matchRibbonBoneNameFromText(node.textContent || "", boneNames);
        });
      }
      nodes.forEach((node) => {
        if (!(node instanceof HTMLElement) || !isVisible(node)) return;
        const matched = boneNames.length
          ? matchRibbonBoneNameFromText(node.textContent || "", boneNames)
          : String(node.textContent || "").trim();
        addName(matched);
      });
    } catch (_) {
      void 0;
    }
    return normalizeRibbonSelectedBoneNames(selected);
  }

  function getRibbonManualSelectedBoneNames(context) {
    const domSelected = getRibbonDirectSelectedBoneNamesFromDom(context?.project);
    if (domSelected.length) return domSelected;
    const reactSelected = normalizeRibbonSelectedBoneNames(context?.selectedBoneNames);
    if (reactSelected.length) return reactSelected;
    return normalizeRibbonSelectedBoneNames([context?.selectedBoneName || ""]);
  }

  function createRibbonBoneNameNormalizer(project) {
    const boneNames = getRibbonProjectBoneNames(project);
    const boneSet = new Set(boneNames);
    return (value) => {
      const name = String(value || "").trim();
      if (!name || name === "root") return "";
      if (!boneSet.size || boneSet.has(name)) return name;
      return matchRibbonBoneNameFromText(name, boneNames);
    };
  }

  function getRibbonPrimarySelectedBoneName(context) {
    const normalizeName = createRibbonBoneNameNormalizer(context?.project);
    const domSelected = getRibbonDirectSelectedBoneNamesFromDom(context?.project)
      .map(normalizeName)
      .filter(Boolean);
    const reactSelected = normalizeRibbonSelectedBoneNames(context?.selectedBoneNames)
      .map(normalizeName)
      .filter(Boolean);
    const reactSingle = normalizeName(context?.selectedBoneName);
    const selectedSet = new Set([
      ...domSelected,
      ...reactSelected,
      ...(reactSingle ? [reactSingle] : [])
    ]);
    const remembered = normalizeName(window.__NovaFlowRibbonPrimarySelectedBoneName);
    if (remembered && (!selectedSet.size || selectedSet.has(remembered))) return remembered;
    if (reactSingle) return reactSingle;
    if (domSelected.length) return domSelected[domSelected.length - 1];
    if (reactSelected.length) return reactSelected[reactSelected.length - 1];
    return "";
  }

  function getRibbonSelectedRootBoneNames(context) {
    const normalizeName = createRibbonBoneNameNormalizer(context?.project);
    const selected = getRibbonManualSelectedBoneNames(context)
      .map(normalizeName)
      .filter(Boolean);
    if (selected.length > 1) return normalizeRibbonSelectedBoneNames(selected);
    const primary = getRibbonPrimarySelectedBoneName(context);
    if (primary) return [primary];
    return normalizeRibbonSelectedBoneNames(selected);
  }

  function getRibbonCurrentSelectedBoneNames(context) {
    return getRibbonSelectedRootBoneNames(context);
  }

  function getRibbonElasticTargetBoneNames(context, animation, autoChainEnabled = true) {
    return getRibbonElasticTargetBoneEntries(context, animation, autoChainEnabled).map((entry) => entry.name);
  }

  function getRibbonManualChainIndexMap(project, selectedNames) {
    const parents = buildRibbonParentMap(project);
    const selected = normalizeRibbonSelectedBoneNames(selectedNames);
    const selectedSet = new Set(selected);
    const indexMap = new Map();
    selected.forEach((name) => {
      let depth = 0;
      let current = name;
      const visited = new Set([current]);
      while (parents.has(current)) {
        const parent = parents.get(current);
        if (!selectedSet.has(parent) || visited.has(parent)) break;
        depth += 1;
        current = parent;
        visited.add(current);
      }
      indexMap.set(name, depth);
    });
    return indexMap;
  }

  function getRibbonElasticTargetBoneEntries(context, animation, autoChainEnabled = true) {
    void animation;
    const rootNames = getRibbonSelectedRootBoneNames(context);
    if (!rootNames.length) return [];
    const entries = [];
    const addEntry = (boneName, chainIndex, sourceName) => {
      const next = String(boneName || "").trim();
      if (!next || entries.some((entry) => entry.name === next)) return;
      const source = String(sourceName || next).trim() || next;
      entries.push({
        name: next,
        chainIndex: Math.max(0, Math.round(Number(chainIndex) || 0)),
        canCreatePreview: true,
        sourceName: source
      });
    };
    if (autoChainEnabled === false) {
      const manualIndexMap = getRibbonManualChainIndexMap(context?.project, rootNames);
      rootNames.forEach((rootName) => {
        const sourceName = String(rootName || "").trim();
        if (!sourceName) return;
        addEntry(sourceName, manualIndexMap.get(sourceName) || 0, sourceName);
      });
      return entries;
    }
    rootNames.forEach((rootName) => {
      const sourceName = String(rootName || "").trim();
      if (!sourceName) return;
      const chainEntries = buildRibbonElasticChainEntries(context.project, sourceName, RIBBON_PRESET_AUTO_CHAIN_MAX_BONES);
      chainEntries.forEach((entry) => {
        addEntry(entry.name, entry.chainIndex, sourceName);
      });
    });
    return entries;
  }

  function getRibbonRotateFrameAngle(frame, fallback = 0) {
    if (!frame || typeof frame !== "object") return fallback;
    const angle = Number(frame.angle);
    if (Number.isFinite(angle)) return angle;
    const value = Number(frame.value);
    if (Number.isFinite(value)) return value;
    return fallback;
  }

  function normalizeRibbonRotateFrames(frames) {
    return (Array.isArray(frames) ? frames : [])
      .map((frame) => ({
        time: roundRibbonElasticTime(frame?.time),
        angle: roundRibbonElasticAngle(getRibbonRotateFrameAngle(frame, 0))
      }))
      .filter((frame) => Number.isFinite(frame.time) && Number.isFinite(frame.angle))
      .sort((a, b) => a.time - b.time);
  }

  function getRibbonRotateSignature(frames) {
    return normalizeRibbonRotateFrames(frames)
      .map((frame) => `${frame.time}:${frame.angle}`)
      .join("|");
  }

  function getRibbonRotateFullSignature(frames) {
    if (!Array.isArray(frames)) return "";
    return `${getRibbonRotateSignature(frames)}::${getRibbonRotateShapeSignature(frames)}`;
  }

  function getRibbonProjectStructureSignature(project) {
    const bones = Array.isArray(project?.bones) ? project.bones : [];
    const boneSignature = bones
      .map((bone) => `${getRibbonBoneName(bone)}>${getRibbonBoneParentName(bone)}`)
      .join("|");
    const animationSignature = Object.keys(project?.animations || {}).sort().join("|");
    return `${boneSignature}::${animationSignature}`;
  }

  function getRibbonProjectTopologySignature(project) {
    if (!project || typeof project !== "object") return "";
    const bones = Array.isArray(project.bones) ? project.bones : [];
    const boneSignature = bones
      .map((bone) => `${getRibbonBoneName(bone)}>${getRibbonBoneParentName(bone)}`)
      .join("|");
    const slots = Array.isArray(project.slots) ? project.slots : [];
    const slotSignature = slots
      .map((slot) => `${String(slot?.name || "").trim()}>${String(slot?.bone || "").trim()}`)
      .join("|");
    const spineVersion = String(project?.skeleton?.spine || "").trim();
    const skeletonHash = String(project?.skeleton?.hash || project?.hash || "").trim();
    return [
      spineVersion,
      skeletonHash,
      boneSignature,
      slotSignature,
      getRibbonProjectSkinSignature(project)
    ].join("::");
  }

  function getRibbonProjectSkinSignature(project) {
    const skins = project?.skins;
    if (Array.isArray(skins)) {
      return skins.map((skin) => {
        const name = String(skin?.name || "default").trim() || "default";
        const attachments = skin?.attachments && typeof skin.attachments === "object" ? skin.attachments : {};
        return `${name}:${Object.keys(attachments).sort().join(",")}`;
      }).join("|");
    }
    if (skins && typeof skins === "object") {
      return Object.keys(skins).sort().map((skinName) => {
        const attachments = skins[skinName] && typeof skins[skinName] === "object" ? skins[skinName] : {};
        return `${skinName}:${Object.keys(attachments).sort().join(",")}`;
      }).join("|");
    }
    return "";
  }

  function getRibbonProjectSignatureCacheKey(project, animationName = "") {
    if (!project || typeof project !== "object") return "";
    const bones = Array.isArray(project.bones) ? project.bones : [];
    const slots = Array.isArray(project.slots) ? project.slots : [];
    const animations = project.animations && typeof project.animations === "object"
      ? Object.keys(project.animations).sort().join("|")
      : "";
    const skins = project?.skins;
    const skinCount = Array.isArray(skins)
      ? skins.length
      : (skins && typeof skins === "object" ? Object.keys(skins).length : 0);
    return [
      String(project?.skeleton?.spine || "").trim(),
      String(project?.skeleton?.hash || project?.hash || "").trim(),
      bones.length,
      slots.length,
      skinCount,
      animations,
      String(animationName || "").trim()
    ].join("::");
  }

  function getRibbonProjectContextSignatureFromProject(project, animationName = "") {
    if (!project || typeof project !== "object") return "";
    const cacheKey = getRibbonProjectSignatureCacheKey(project, animationName);
    const cached = ribbonProjectContextSignatureCache.get(project);
    if (cached?.key === cacheKey && cached.signature) return cached.signature;
    const slots = Array.isArray(project.slots) ? project.slots : [];
    const slotSignature = slots
      .map((slot) => `${String(slot?.name || "").trim()}>${String(slot?.bone || "").trim()}`)
      .join("|");
    const spineVersion = String(project?.skeleton?.spine || "").trim();
    const skeletonHash = String(project?.skeleton?.hash || project?.hash || "").trim();
    const name = String(animationName || "").trim();
    const signature = [
      spineVersion,
      skeletonHash,
      getRibbonProjectStructureSignature(project),
      slotSignature,
      getRibbonProjectSkinSignature(project),
      name && project?.animations?.[name] ? name : ""
    ].join("::");
    ribbonProjectContextSignatureCache.set(project, {
      key: cacheKey,
      signature
    });
    return signature;
  }

  function getRibbonProjectContextSignature(context) {
    return getRibbonProjectContextSignatureFromProject(context?.project, context?.animationName || "");
  }

  function countRibbonSkinAttachmentSlots(project) {
    const skins = project?.skins;
    if (Array.isArray(skins)) {
      return skins.reduce((sum, skin) => {
        const attachments = skin?.attachments && typeof skin.attachments === "object" ? skin.attachments : {};
        return sum + Object.keys(attachments).length;
      }, 0);
    }
    if (skins && typeof skins === "object") {
      return Object.values(skins).reduce((sum, attachments) => (
        sum + (attachments && typeof attachments === "object" ? Object.keys(attachments).length : 0)
      ), 0);
    }
    return 0;
  }

  function getRibbonProjectCompletenessScore(project) {
    if (!project || typeof project !== "object") return -100000;
    const bones = Array.isArray(project.bones) ? project.bones.length : 0;
    const slots = Array.isArray(project.slots) ? project.slots.length : 0;
    const animations = project.animations && typeof project.animations === "object"
      ? Object.keys(project.animations).length
      : 0;
    return bones + slots * 4 + countRibbonSkinAttachmentSlots(project) * 2 + animations * 3;
  }

  function cloneRibbonProjectIdentityValue(value, depth = 0) {
    if (depth > 32) return value;
    if (value === null || typeof value !== "object") return value;
    if (typeof File !== "undefined" && value instanceof File) return value;
    if (typeof Blob !== "undefined" && value instanceof Blob) return value;
    if (typeof Element !== "undefined" && value instanceof Element) return value;
    if (Array.isArray(value)) {
      return value.map((item) => cloneRibbonProjectIdentityValue(item, depth + 1));
    }
    const clone = {};
    Object.getOwnPropertyNames(value).forEach((key) => {
      const descriptor = Object.getOwnPropertyDescriptor(value, key);
      if (descriptor && ("get" in descriptor || "set" in descriptor)) return;
      const nextValue = cloneRibbonProjectIdentityValue(value[key], depth + 1);
      if (descriptor && descriptor.enumerable === false) {
        setRibbonHiddenValue(clone, key, nextValue);
      } else {
        clone[key] = nextValue;
      }
    });
    return clone;
  }

  function cloneRibbonProjectIdentitySnapshot(project) {
    return cloneRibbonProjectIdentityValue(project);
  }

  function createRibbonProjectIdentity(snapshot, project, reason = "") {
    if (!snapshot) return null;
    const projectSnapshot = cloneRibbonProjectIdentitySnapshot(project);
    const animationName = String(snapshot?.animationName || "").trim();
    if (animationName && projectSnapshot?.animations?.[animationName]) {
      restoreRibbonRotateShapesForAnimation(projectSnapshot, animationName, projectSnapshot.animations[animationName]);
    }
    return {
      ...snapshot,
      projectSnapshot,
      reason: String(reason || "identity")
    };
  }

  function getRibbonProjectIdentitySnapshot(project, animationName = "") {
    if (!project || typeof project !== "object") return null;
    const cacheKey = getRibbonProjectSignatureCacheKey(project, animationName);
    const cached = ribbonProjectIdentitySnapshotCache.get(project);
    if (cached?.key === cacheKey && cached.snapshot) return cached.snapshot;
    const bones = Array.isArray(project.bones) ? project.bones : [];
    const slots = Array.isArray(project.slots) ? project.slots : [];
    const animations = project.animations && typeof project.animations === "object"
      ? Object.keys(project.animations)
      : [];
    const projectRef = bones.length ? bones : (project?.skeleton || null);
    const topologySignature = getRibbonProjectTopologySignature(project);
    if (!projectRef || !topologySignature) return null;
    const snapshot = {
      projectRef,
      topologySignature,
      contextSignature: getRibbonProjectContextSignatureFromProject(project, animationName),
      boneCount: bones.length,
      slotCount: slots.length,
      attachmentCount: countRibbonSkinAttachmentSlots(project),
      animationCount: animations.length,
      score: getRibbonProjectCompletenessScore(project),
      animationName: String(animationName || "").trim(),
      createdAt: Date.now()
    };
    ribbonProjectIdentitySnapshotCache.set(project, {
      key: cacheKey,
      snapshot
    });
    return snapshot;
  }

  function isRibbonProjectIdentityProtectionActive(animationName = "") {
    const name = String(animationName || "").trim();
    return ribbonParameterPresetSessionState !== "idle" ||
      !!ribbonParameterPresetTargetScope ||
      isRibbonElasticityPreviewArmed(name) ||
      ribbonElasticityPreviewRegistry.size > 0 ||
      isRibbonParameterPreviewGuardActive(name);
  }

  function isRibbonProjectIdentitySnapshotCompatible(snapshot, identity = ribbonElasticityProjectIdentity) {
    if (!identity || !snapshot) return true;
    if (snapshot.topologySignature !== identity.topologySignature) return false;
    if (snapshot.boneCount < identity.boneCount) return false;
    if (snapshot.slotCount < identity.slotCount) return false;
    if (snapshot.attachmentCount < identity.attachmentCount) return false;
    if (snapshot.score + 12 < identity.score) return false;
    return true;
  }

  function rememberRibbonProjectIdentity(project, animationName = "", reason = "") {
    const snapshot = getRibbonProjectIdentitySnapshot(project, animationName);
    if (!snapshot) return ribbonElasticityProjectIdentity;
    if (shouldResetRibbonStateForProjectSwitch(snapshot.projectRef, snapshot)) {
      return resetRibbonProjectScopedStateForSwitch(project, snapshot, reason || "project-switch");
    }
    const protectedIdentity = isRibbonProjectIdentityProtectionActive(animationName);
    if (!ribbonElasticityProjectIdentity) {
      ribbonElasticityProjectIdentity = createRibbonProjectIdentity(snapshot, project, reason || "initial");
      return ribbonElasticityProjectIdentity;
    }
    if (isRibbonProjectIdentitySnapshotCompatible(snapshot)) {
      const sameIdentity =
        snapshot.projectRef === ribbonElasticityProjectIdentity.projectRef &&
        snapshot.contextSignature === ribbonElasticityProjectIdentity.contextSignature &&
        snapshot.topologySignature === ribbonElasticityProjectIdentity.topologySignature;
      if (sameIdentity && protectedIdentity) return ribbonElasticityProjectIdentity;
      if (
        sameIdentity &&
        Date.now() - Number(ribbonElasticityProjectIdentity.createdAt || 0) < RIBBON_PROJECT_IDENTITY_REFRESH_MIN_INTERVAL_MS
      ) {
        return ribbonElasticityProjectIdentity;
      }
      if (
        snapshot.projectRef === ribbonElasticityProjectIdentity.projectRef ||
        snapshot.score >= ribbonElasticityProjectIdentity.score ||
        !protectedIdentity
      ) {
        ribbonElasticityProjectIdentity = createRibbonProjectIdentity(snapshot, project, reason || "refresh");
      }
      return ribbonElasticityProjectIdentity;
    }
    if (!protectedIdentity) {
      ribbonElasticityProjectIdentity = createRibbonProjectIdentity(snapshot, project, reason || "project-reset");
    }
    return ribbonElasticityProjectIdentity;
  }

  function getRibbonProjectIdentityValidation(context, reason = "") {
    const snapshot = getRibbonProjectIdentitySnapshot(context?.project, context?.animationName || "");
    if (!snapshot) {
      return { accepted: false, snapshot, identity: ribbonElasticityProjectIdentity, reason: "missing-project-identity" };
    }
    if (!ribbonElasticityProjectIdentity) {
      ribbonElasticityProjectIdentity = createRibbonProjectIdentity(snapshot, context?.project, reason || "initial");
      return { accepted: true, snapshot, identity: ribbonElasticityProjectIdentity, reason: "identity-created" };
    }
    const accepted = isRibbonProjectIdentitySnapshotCompatible(snapshot);
    if (accepted) {
      if (!isRibbonProjectIdentityProtectionActive(context?.animationName || "")) {
        rememberRibbonProjectIdentity(context?.project, context?.animationName || "", reason || "identity-compatible");
      }
    }
    return {
      accepted,
      snapshot,
      identity: ribbonElasticityProjectIdentity,
      reason: accepted ? "identity-compatible" : "project-shrink-blocked"
    };
  }

  function writeRibbonProjectIdentityBlockStats(reason, context, validation) {
    const snapshot = validation?.snapshot || null;
    const identity = validation?.identity || ribbonElasticityProjectIdentity || null;
    window.__NovaFlowRibbonElasticityLastStats = {
      ...(window.__NovaFlowRibbonElasticityLastStats || {}),
      reason,
      skipped: validation?.reason || "project-shrink-blocked",
      contextAccepted: false,
      projectSignature: snapshot?.contextSignature || getRibbonProjectContextSignature(context),
      lockedProjectSignature: String(ribbonParameterPresetTargetScope?.projectSignature || ""),
      projectScore: snapshot?.score ?? getRibbonProjectCompletenessScore(context?.project),
      lockedProjectScore: identity?.score ?? null,
      projectBones: snapshot?.boneCount ?? (Array.isArray(context?.project?.bones) ? context.project.bones.length : 0),
      lockedProjectBones: identity?.boneCount ?? null,
      projectSlots: snapshot?.slotCount ?? (Array.isArray(context?.project?.slots) ? context.project.slots.length : 0),
      lockedProjectSlots: identity?.slotCount ?? null,
      projectAttachments: snapshot?.attachmentCount ?? countRibbonSkinAttachmentSlots(context?.project),
      lockedProjectAttachments: identity?.attachmentCount ?? null,
      animation: context?.animationName || ""
    };
  }

  function armRibbonElasticityInitialRestoreGuard(animationName = "", reason = "initial-restore", durationMs = 1800) {
    const name = String(animationName || "").trim();
    if (!name) return false;
    ribbonElasticityInitialRestoreGuardAnimationName = name;
    ribbonElasticityInitialRestoreGuardReason = String(reason || "initial-restore");
    ribbonElasticityInitialRestoreGuardUntil = Date.now() + Math.max(240, Math.round(Number(durationMs) || 1800));
    return true;
  }

