  function getRibbonRotateFrameOutputKey(referenceFrames = null, project = null) {
    const spineVersion = getRibbonProjectSpineVersion(project);
    if (/^[4-9](?:\.|$)/.test(spineVersion)) return "value";
    if (/^[0-3](?:\.|$)/.test(spineVersion)) return "angle";
    const projectKey = getRibbonProjectRotateFrameShapeOutputKey(project);
    if (projectKey) return projectKey;
    return getRibbonRotateFrameShapeOutputKey(referenceFrames) || "angle";
  }

  function resolveRibbonRotateFrameOutputKey(referenceFrames = null, project = null, explicitOutputKey = "") {
    const spineVersion = getRibbonProjectSpineVersion(project);
    const projectKey = getRibbonRotateFrameOutputKey(referenceFrames, project);
    if (/^[0-9](?:\.|$)/.test(spineVersion)) return projectKey;
    const explicit = String(explicitOutputKey || "").trim();
    return explicit === "value" || explicit === "angle" ? explicit : projectKey;
  }

  function getRibbonStoredRotateOutputKey(timeline, referenceFrames = null, project = null) {
    const explicit = String(timeline?.__novaflowRibbonRotateOutputKey || "").trim();
    return resolveRibbonRotateFrameOutputKey(referenceFrames, project, explicit);
  }

  function serializeRibbonRotateFramesForTimeline(frames, referenceFrames = null, project = null, explicitOutputKey = "") {
    const key = resolveRibbonRotateFrameOutputKey(referenceFrames, project, explicitOutputKey);
    return normalizeRibbonRotateFrames(frames).map((frame) => (
      key === "value"
        ? { time: frame.time, value: frame.angle }
        : { time: frame.time, angle: frame.angle }
    ));
  }

  function cloneRibbonRotateFramesPreserveShape(frames) {
    return (Array.isArray(frames) ? frames : [])
      .filter((frame) => frame && typeof frame === "object")
      .map((frame) => {
        const clone = { ...frame };
        if (Array.isArray(frame.curve)) clone.curve = frame.curve.slice();
        return clone;
      });
  }

  function getRibbonRotateShapeSignature(frames) {
    return cloneRibbonRotateFramesPreserveShape(frames)
      .map((frame) => JSON.stringify(frame))
      .join("|");
  }

  function cloneRibbonRotateFramesForRestoreWriteback(frames, fallbackFrames, project = null, explicitOutputKey = "") {
    const shaped = cloneRibbonRotateFramesPreserveShape(frames);
    const outputKey = resolveRibbonRotateFrameOutputKey(shaped.length ? shaped : fallbackFrames, project, explicitOutputKey);
    if (shaped.length) {
      const shapeKey = getRibbonRotateFrameShapeOutputKey(shaped);
      if ((outputKey === "value" && shapeKey !== "value") || (outputKey === "angle" && shapeKey !== "angle")) {
        return serializeRibbonRotateFramesForTimeline(fallbackFrames, shaped, project, outputKey);
      }
      return shaped;
    }
    return serializeRibbonRotateFramesForTimeline(fallbackFrames, frames, project, explicitOutputKey);
  }

  function writeRibbonRotateFramesForProjectShape(timeline, frames, project = null, explicitOutputKey = "") {
    if (!timeline || typeof timeline !== "object") return "";
    const shaped = cloneRibbonRotateFramesPreserveShape(frames);
    const outputKey = resolveRibbonRotateFrameOutputKey(shaped, project, explicitOutputKey);
    timeline.rotate = cloneRibbonRotateFramesForRestoreWriteback(shaped, shaped, project, outputKey);
    setRibbonHiddenValue(timeline, "__novaflowRibbonRotateOutputKey", outputKey);
    return outputKey;
  }

  function rememberRibbonRotateOutputKey(timeline, referenceFrames = null, project = null) {
    if (!timeline || typeof timeline !== "object") return "angle";
    const key = getRibbonRotateFrameOutputKey(referenceFrames, project);
    setRibbonHiddenValue(timeline, "__novaflowRibbonRotateOutputKey", key);
    return key;
  }

  function clearRibbonRotateShapePreservationRegistry() {
    ribbonRotateShapePreservationRegistry.clear();
    ribbonRotateShapePreservationProjectSignature = "";
  }

  function getRibbonRotateShapePreservationProjectSignature(project, animationName = "") {
    if (!project || typeof project !== "object") return "";
    return getRibbonProjectTopologySignature(project) ||
      getRibbonProjectContextSignatureFromProject(project, animationName);
  }

  function syncRibbonRotateShapePreservationProject(project, animationName = "") {
    const signature = getRibbonRotateShapePreservationProjectSignature(project, animationName);
    if (!signature) return "";
    if (ribbonRotateShapePreservationProjectSignature && ribbonRotateShapePreservationProjectSignature !== signature) {
      clearRibbonRotateShapePreservationRegistry();
    }
    ribbonRotateShapePreservationProjectSignature = signature;
    return signature;
  }

  function getRibbonRotateShapePreservationKey(project, animationName, boneName) {
    const projectSignature = syncRibbonRotateShapePreservationProject(project, animationName);
    const name = String(boneName || "").trim();
    const animationKey = String(animationName || "").trim();
    if (!projectSignature || !animationKey || !name) return "";
    return `${projectSignature}::${animationKey}::${name}`;
  }

  function rememberRibbonRotateShapeForFrames(project, animationName, boneName, frames) {
    const shapeRotate = cloneRibbonRotateFramesPreserveShape(frames);
    if (!shapeRotate.length) return false;
    const key = getRibbonRotateShapePreservationKey(project, animationName, boneName);
    if (!key) return false;
    const signature = getRibbonRotateSignature(shapeRotate);
    const shapeSignature = getRibbonRotateShapeSignature(shapeRotate);
    const shapeOutputKey = getRibbonRotateFrameShapeOutputKey(shapeRotate);
    const outputKey = getRibbonRotateFrameOutputKey(shapeRotate, project);
    const existing = ribbonRotateShapePreservationRegistry.get(key) || null;
    if (existing && existing.signature === signature) {
      if (existing.shapeSignature === shapeSignature) return false;
      if (existing.outputKey === "value" && shapeOutputKey !== "value") return false;
    }
    ribbonRotateShapePreservationRegistry.set(key, {
      rotate: shapeRotate,
      signature,
      shapeSignature,
      outputKey
    });
    return true;
  }

  function rememberRibbonRotateShapeForTimeline(project, animationName, boneName, timeline) {
    if (!timeline || typeof timeline !== "object" || !Array.isArray(timeline.rotate)) return false;
    return rememberRibbonRotateShapeForFrames(project, animationName, boneName, timeline.rotate);
  }

  function rememberRibbonRotateShapesFromAnimation(project, animationName, animation = null) {
    const targetAnimation = animation || project?.animations?.[animationName];
    const bones = targetAnimation?.bones && typeof targetAnimation.bones === "object" ? targetAnimation.bones : null;
    if (!bones) return 0;
    let remembered = 0;
    Object.keys(bones).forEach((boneName) => {
      if (rememberRibbonRotateShapeForTimeline(project, animationName, boneName, bones[boneName])) remembered += 1;
    });
    return remembered;
  }

  function getRibbonRotateShapePreservationEntry(project, animationName, boneName) {
    const key = getRibbonRotateShapePreservationKey(project, animationName, boneName);
    return key ? ribbonRotateShapePreservationRegistry.get(key) || null : null;
  }

  function restoreRibbonRotateShapeForTimeline(project, animationName, boneName, timeline) {
    if (!timeline || typeof timeline !== "object" || !Array.isArray(timeline.rotate)) return false;
    const entry = getRibbonRotateShapePreservationEntry(project, animationName, boneName);
    if (!entry || !Array.isArray(entry.rotate) || !entry.rotate.length) return false;
    const currentSignature = getRibbonRotateSignature(timeline.rotate);
    if (currentSignature !== entry.signature) return false;
    const currentShapeSignature = getRibbonRotateShapeSignature(timeline.rotate);
    if (currentShapeSignature === entry.shapeSignature) return false;
    const outputKey = resolveRibbonRotateFrameOutputKey(entry.rotate, project, entry.outputKey);
    timeline.rotate = cloneRibbonRotateFramesForRestoreWriteback(entry.rotate, entry.rotate, project, outputKey);
    setRibbonHiddenValue(timeline, "__novaflowRibbonRotateOutputKey", outputKey);
    return true;
  }

  function getRibbonRotateFramePreferredValue(frame, outputKey = "") {
    if (!frame || typeof frame !== "object") return 0;
    const primary = outputKey === "value" ? Number(frame.value) : Number(frame.angle);
    if (Number.isFinite(primary)) return primary;
    const fallback = outputKey === "value" ? Number(frame.angle) : Number(frame.value);
    return Number.isFinite(fallback) ? fallback : 0;
  }

  function normalizeRibbonRotateTimelineForProjectVersion(project, animationName, boneName, timeline) {
    if (!timeline || typeof timeline !== "object" || !Array.isArray(timeline.rotate)) return false;
    const outputKey = getRibbonRotateFrameOutputKey(timeline.rotate, project);
    if (outputKey !== "value" && outputKey !== "angle") return false;
    const needsNormalize = timeline.rotate.some((frame) => {
      if (!frame || typeof frame !== "object") return false;
      const hasValue = Object.prototype.hasOwnProperty.call(frame, "value");
      const hasAngle = Object.prototype.hasOwnProperty.call(frame, "angle");
      if (!hasValue && !hasAngle) return false;
      return outputKey === "value" ? hasAngle : hasValue;
    });
    if (!needsNormalize) {
      setRibbonHiddenValue(timeline, "__novaflowRibbonRotateOutputKey", outputKey);
      return false;
    }
    const nextRotate = timeline.rotate.map((frame) => {
      if (!frame || typeof frame !== "object") return frame;
      const hasValue = Object.prototype.hasOwnProperty.call(frame, "value");
      const hasAngle = Object.prototype.hasOwnProperty.call(frame, "angle");
      if (!hasValue && !hasAngle) return frame;
      const nextFrame = { ...frame };
      if (Array.isArray(frame.curve)) nextFrame.curve = frame.curve.slice();
      const nextValue = getRibbonRotateFramePreferredValue(frame, outputKey);
      if (outputKey === "value") {
        if (!hasAngle && hasValue) return frame;
        nextFrame.value = nextValue;
        delete nextFrame.angle;
        return nextFrame;
      }
      if (!hasValue && hasAngle) return frame;
      nextFrame.angle = nextValue;
      delete nextFrame.value;
      return nextFrame;
    });
    timeline.rotate = nextRotate;
    setRibbonHiddenValue(timeline, "__novaflowRibbonRotateOutputKey", outputKey);
    rememberRibbonRotateShapeForTimeline(project, animationName, boneName, timeline);
    return true;
  }

  function restoreRibbonRotateShapesForAnimation(project, animationName, animation = null) {
    const targetAnimation = animation || project?.animations?.[animationName];
    const bones = targetAnimation?.bones && typeof targetAnimation.bones === "object" ? targetAnimation.bones : null;
    if (!bones) return 0;
    syncRibbonRotateShapePreservationProject(project, animationName);
    let restored = 0;
    Object.keys(bones).forEach((boneName) => {
      const timeline = bones[boneName];
      const shapeRestored = restoreRibbonRotateShapeForTimeline(project, animationName, boneName, timeline);
      const versionNormalized = normalizeRibbonRotateTimelineForProjectVersion(project, animationName, boneName, timeline);
      if (shapeRestored || versionNormalized) restored += 1;
    });
    return restored;
  }

  function getRibbonRestoreShapeRotate(timeline) {
    return Array.isArray(timeline?.__novaflowRibbonElasticRestoreShapeRotate)
      ? cloneRibbonRotateFramesPreserveShape(timeline.__novaflowRibbonElasticRestoreShapeRotate)
      : null;
  }

  function getRibbonSourceShapeRotate(timeline) {
    return Array.isArray(timeline?.__novaflowRibbonElasticSourceShapeRotate)
      ? cloneRibbonRotateFramesPreserveShape(timeline.__novaflowRibbonElasticSourceShapeRotate)
      : null;
  }

  function getRibbonRestoreShapeForSource(timeline, restoreSource, project = null) {
    const restoreSignature = getRibbonRotateSignature(restoreSource);
    const existingShape = getRibbonRestoreShapeRotate(timeline);
    if (existingShape && existingShape.length && getRibbonRotateSignature(existingShape) === restoreSignature) {
      const outputKey = getRibbonStoredRotateOutputKey(timeline, existingShape, project);
      const shapeKey = getRibbonRotateFrameShapeOutputKey(existingShape);
      if ((outputKey === "value" && shapeKey !== "value") || (outputKey === "angle" && shapeKey !== "angle")) {
        return serializeRibbonRotateFramesForTimeline(restoreSource, existingShape, project, outputKey);
      }
      return existingShape;
    }
    const currentShape = cloneRibbonRotateFramesPreserveShape(timeline?.rotate);
    if (currentShape.length && getRibbonRotateSignature(currentShape) === restoreSignature) {
      const outputKey = getRibbonStoredRotateOutputKey(timeline, currentShape, project);
      const shapeKey = getRibbonRotateFrameShapeOutputKey(currentShape);
      if ((outputKey === "value" && shapeKey !== "value") || (outputKey === "angle" && shapeKey !== "angle")) {
        return serializeRibbonRotateFramesForTimeline(restoreSource, currentShape, project, outputKey);
      }
      return currentShape;
    }
    const outputKey = getRibbonStoredRotateOutputKey(timeline, currentShape.length ? currentShape : timeline?.rotate, project);
    return serializeRibbonRotateFramesForTimeline(restoreSource, currentShape.length ? currentShape : timeline?.rotate, project, outputKey);
  }

  function shouldResetRibbonRegistryForProjectRefChange(nextIdentity) {
    if (!ribbonElasticityProjectIdentity || !nextIdentity) return true;
    if (!isRibbonProjectIdentitySnapshotCompatible(nextIdentity)) return true;
    const previousSignature = String(ribbonElasticityProjectIdentity.topologySignature || "");
    const nextSignature = String(nextIdentity.topologySignature || "");
    return !!(previousSignature && nextSignature && previousSignature !== nextSignature);
  }

  function getRibbonProjectIdentitySignaturePart(identity, index) {
    return String(identity?.topologySignature || "").split("::")[index] || "";
  }

  function isRibbonProjectIdentitySnapshotProjectSwitch(previousIdentity, nextIdentity, previousProjectRef = null) {
    if (!previousIdentity || !nextIdentity) return false;
    const previousRef = previousProjectRef || previousIdentity.projectRef || null;
    if (!previousRef || previousRef === nextIdentity.projectRef) return false;
    const previousSignature = String(previousIdentity.topologySignature || "");
    const nextSignature = String(nextIdentity.topologySignature || "");
    if (!previousSignature || !nextSignature || previousSignature === nextSignature) return false;
    return true;
  }

  function shouldResetRibbonStateForProjectSwitch(projectRef, nextIdentity) {
    if (!ribbonElasticityProjectIdentity || !nextIdentity) return false;
    const previousRef = ribbonElasticityRegistryProjectRef || ribbonElasticityProjectIdentity.projectRef || null;
    if (!projectRef || projectRef !== nextIdentity.projectRef) return false;
    return isRibbonProjectIdentitySnapshotProjectSwitch(ribbonElasticityProjectIdentity, nextIdentity, previousRef);
  }

  function clearRibbonElasticProjectScopedState(options = {}) {
    clearRibbonElasticityPreviewArmed();
    cancelPendingRibbonElasticityResponse();
    cancelPendingRibbonParameterPresetApply();
    cancelPendingRibbonSelectionPresetPreview();
    cancelPendingRibbonPreviewProjectCommit();
    clearNovaflowSpineCurrentChainFilterCache();
    ribbonElasticityBaselineRegistry.clear();
    ribbonElasticityBaselineSnapshotRegistry.clear();
    ribbonElasticityPreviewRegistry.clear();
    ribbonElasticityInitialSnapshotRegistry.clear();
    clearRibbonElasticityProjectInitialSnapshotRegistry();
    clearRibbonRotateShapePreservationRegistry();
    ribbonProjectRotateOutputKeyCache = new WeakMap();
    ribbonProjectContextSignatureCache = new WeakMap();
    ribbonProjectIdentitySnapshotCache = new WeakMap();
    ribbonReactFiberContextCache = { fiber: null, createdAt: 0 };
    ribbonElasticityAutoChainPreviewScopes.clear();
    ribbonElasticityPreActionSnapshot = null;
    ribbonParameterPresetPreviewApplyKey = "";
    clearRibbonElasticityInitialRestoreGuard();
    clearRibbonParameterPresetSession("", { clearSelect: true });
    if (options.clearIdentity === true) ribbonElasticityProjectIdentity = null;
    if (options.clearProjectRef === true) ribbonElasticityRegistryProjectRef = null;
  }

  function resetRibbonProjectScopedStateForSwitch(project, nextIdentity, reason = "project-switch") {
    const previousIdentity = ribbonElasticityProjectIdentity;
    clearRibbonElasticProjectScopedState({ clearIdentity: true, clearProjectRef: true });
    ribbonElasticityRegistryProjectRef = nextIdentity?.projectRef || (Array.isArray(project?.bones) ? project.bones : (project?.skeleton || null));
    ribbonElasticityProjectIdentity = nextIdentity
      ? createRibbonProjectIdentity(nextIdentity, project, reason)
      : null;
    window.__NovaFlowRibbonElasticityLastStats = {
      ...(window.__NovaFlowRibbonElasticityLastStats || {}),
      reason: "project-switch-state-reset",
      trigger: String(reason || "project-switch"),
      previousSpineVersion: getRibbonProjectIdentitySignaturePart(previousIdentity, 0),
      spineVersion: getRibbonProjectIdentitySignaturePart(nextIdentity, 0),
      previousProjectHash: getRibbonProjectIdentitySignaturePart(previousIdentity, 1),
      projectHash: getRibbonProjectIdentitySignaturePart(nextIdentity, 1),
      projectSignature: nextIdentity?.contextSignature || "",
      previousProjectSignature: previousIdentity?.contextSignature || "",
      contextAccepted: true
    };
    return ribbonElasticityProjectIdentity;
  }

  function synchronizeRibbonElasticRegistryProject(project) {
    const projectRef = Array.isArray(project?.bones) ? project.bones : (project?.skeleton || null);
    if (!projectRef) return;
    const nextIdentity = getRibbonProjectIdentitySnapshot(project, "");
    if (shouldResetRibbonStateForProjectSwitch(projectRef, nextIdentity)) {
      resetRibbonProjectScopedStateForSwitch(project, nextIdentity, "registry-project-switch");
      return;
    }
    if (
      ribbonElasticityProjectIdentity &&
      isRibbonProjectIdentityProtectionActive() &&
      !isRibbonProjectIdentitySnapshotCompatible(nextIdentity)
    ) {
      writeRibbonProjectIdentityBlockStats("project-registry-shrink-blocked", {
        project,
        animationName: nextIdentity?.animationName || ""
      }, {
        accepted: false,
        snapshot: nextIdentity,
        identity: ribbonElasticityProjectIdentity,
        reason: "project-shrink-blocked"
      });
      return;
    }
    if (
      ribbonElasticityRegistryProjectRef &&
      ribbonElasticityRegistryProjectRef !== projectRef &&
      shouldResetRibbonRegistryForProjectRefChange(nextIdentity)
    ) {
      clearRibbonElasticProjectScopedState();
    }
    ribbonElasticityRegistryProjectRef = projectRef;
    if (nextIdentity) {
      ribbonElasticityProjectIdentity = createRibbonProjectIdentity(
        nextIdentity,
        project,
        ribbonElasticityProjectIdentity ? "registry-sync" : "registry-initial"
      );
    }
  }

  function normalizeRibbonElasticityApplyReason(reason) {
    return String(reason || "").trim();
  }

  function isRibbonElasticityPresetReason(reason) {
    return normalizeRibbonElasticityApplyReason(reason).toLowerCase().includes("preset");
  }

  function isRibbonElasticityWriteReason(reason) {
    return normalizeRibbonElasticityApplyReason(reason).toLowerCase() === "write";
  }

  function isRibbonElasticityRestoreReason(reason) {
    return normalizeRibbonElasticityApplyReason(reason).toLowerCase() === "restore";
  }

  function isRibbonEventPreviewReason(reason) {
    return normalizeRibbonElasticityApplyReason(reason).toLowerCase().includes("event");
  }

  function armRibbonElasticityPreview(animationName = "") {
    ribbonElasticityPreviewArmed = true;
    ribbonElasticityPreviewArmedAnimationName = String(animationName || "").trim();
  }

  function clearRibbonElasticityPreviewArmed(animationName = "") {
    const name = String(animationName || "").trim();
    if (name && ribbonElasticityPreviewArmedAnimationName && ribbonElasticityPreviewArmedAnimationName !== name) return;
    ribbonElasticityPreviewArmed = false;
    ribbonElasticityPreviewArmedAnimationName = "";
  }

  function isRibbonElasticityPreviewArmed(animationName = "") {
    if (!ribbonElasticityPreviewArmed) return false;
    const name = String(animationName || "").trim();
    return !name || !ribbonElasticityPreviewArmedAnimationName || ribbonElasticityPreviewArmedAnimationName === name;
  }

  function hasRibbonElasticityPreviewTargets(animationName = "") {
    const scope = getRibbonElasticPreviewScope(animationName, false);
    return !!(scope && scope.targets instanceof Set && scope.targets.size > 0);
  }

  function shouldApplyRibbonElasticityForReason(reason, animationName = "") {
    if (isRibbonElasticityRestoreReason(reason)) return true;
    if (isRibbonElasticityPresetReason(reason)) return true;
    if (isRibbonEventPreviewReason(reason)) return hasRibbonEventImpulsePoints(document);
    if (isRibbonElasticityWriteReason(reason)) {
      return isRibbonParameterPresetSessionActive(animationName) ||
        isRibbonElasticityPreviewArmed(animationName) ||
        hasRibbonElasticityPreviewTargets(animationName) ||
        hasRibbonEventImpulsePoints(document);
    }
    return isRibbonElasticityPreviewArmed(animationName);
  }

  function cancelPendingRibbonParameterPresetApply(options = {}) {
    ribbonParameterPresetOverrideToken += 1;
    ribbonParameterPresetPreviewApplyKey = "";
    if (options.clearTargetScope !== false) ribbonParameterPresetTargetScope = null;
  }

  function cancelPendingRibbonSelectionPresetPreview() {
    ribbonSelectionPresetPreviewToken += 1;
    ribbonSelectionPresetPreviewReason = "";
    if (ribbonSelectionPresetPreviewTimer) {
      window.clearTimeout(ribbonSelectionPresetPreviewTimer);
      ribbonSelectionPresetPreviewTimer = 0;
    }
    if (ribbonSelectionPresetPreviewFrame && typeof window.cancelAnimationFrame === "function") {
      window.cancelAnimationFrame(ribbonSelectionPresetPreviewFrame);
    }
    ribbonSelectionPresetPreviewFrame = 0;
  }

  function cloneRibbonParameterPresetTargetEntry(entry) {
    if (!entry || typeof entry !== "object") return null;
    const name = String(entry.name || "").trim();
    if (!name || name === "root") return null;
    const sourceName = String(entry.sourceName || name).trim() || name;
    return {
      name,
      chainIndex: getRibbonChainIndexValue(entry.chainIndex),
      canCreatePreview: entry.canCreatePreview !== false,
      sourceName
    };
  }

  function captureRibbonParameterPresetTargetScope(context, animation, autoChainEnabled = isRibbonAutoChainEnabled(document), reason = "preset") {
    const animationName = String(context?.animationName || "").trim();
    if (!animationName || !animation || typeof animation !== "object") {
      ribbonParameterPresetTargetScope = null;
      return null;
    }
    const identityValidation = getRibbonProjectIdentityValidation(context, reason);
    if (!identityValidation.accepted) {
      writeRibbonProjectIdentityBlockStats(reason, context, identityValidation);
      return null;
    }
    const targetEntries = getRibbonElasticTargetBoneEntries(context, animation, autoChainEnabled)
      .map(cloneRibbonParameterPresetTargetEntry)
      .filter(Boolean);
    const autoChain = autoChainEnabled !== false;
    ribbonParameterPresetTargetScope = {
      animationName,
      autoChain,
      reason: String(reason || ""),
      createdAt: Date.now(),
      projectSignature: getRibbonProjectContextSignature(context),
      projectScore: getRibbonProjectCompletenessScore(context?.project),
      targetEntries,
      signature: targetEntries.map((entry) => `${entry.sourceName}:${entry.name}:${entry.chainIndex}`).join("|")
    };
    return ribbonParameterPresetTargetScope;
  }

  function shouldUseRibbonParameterPresetTargetScope(reasonKey, animationName = "") {
    const normalized = normalizeRibbonElasticityApplyReason(reasonKey).toLowerCase();
    return (
      isRibbonElasticityPresetReason(normalized) ||
      normalized === "parameter-preview" ||
      normalized.includes("whip-strength") ||
      isRibbonParameterPresetSessionActive(animationName)
    );
  }

  function shouldUseRibbonParameterPresetCalculation(reasonKey, animationName = "") {
    const normalized = normalizeRibbonElasticityApplyReason(reasonKey).toLowerCase();
    return (
      isRibbonParameterPresetSessionActive(animationName) ||
      normalized === "parameter-preview" ||
      isRibbonElasticityPresetReason(normalized) ||
      normalized.includes("whip-strength")
    );
  }

  function getRibbonParameterPresetScopedTargetEntries(context, animation, autoChainEnabled, reasonKey = "") {
    const animationName = String(context?.animationName || "").trim();
    const autoChain = autoChainEnabled !== false;
    if (shouldUseRibbonParameterPresetTargetScope(reasonKey, animationName)) {
      const scope = ribbonParameterPresetTargetScope;
      if (scope && scope.animationName === animationName && scope.autoChain === autoChain) {
        return scope.targetEntries.map(cloneRibbonParameterPresetTargetEntry).filter(Boolean);
      }
      const nextScope = captureRibbonParameterPresetTargetScope(context, animation, autoChain, reasonKey);
      if (nextScope) return nextScope.targetEntries.map(cloneRibbonParameterPresetTargetEntry).filter(Boolean);
    }
    return getRibbonElasticTargetBoneEntries(context, animation, autoChainEnabled);
  }

  function normalizeRibbonParameterPresetSessionState(state) {
    const value = String(state || "").trim().toLowerCase();
    if (value === "preview" || value === "committed") return value;
    return "idle";
  }

  function setRibbonParameterPresetSessionState(state, animationName = "") {
    const nextState = normalizeRibbonParameterPresetSessionState(state);
    ribbonParameterPresetSessionState = nextState;
    ribbonParameterPresetSessionAnimationName = nextState === "idle" ? "" : String(animationName || "").trim();
    if (nextState === "idle") {
      ribbonParameterPresetTargetScope = null;
      ribbonParameterPresetSessionWhipValue = RIBBON_WHIP_STRENGTH_DEFAULT;
      ribbonParameterPresetSessionWhipAnimationName = "";
      ribbonParameterPreviewGuardUntil = 0;
      ribbonParameterPreviewGuardAnimationName = "";
      cancelPendingRibbonSelectionPresetPreview();
    }
  }

  function isRibbonParameterPresetSessionState(state, animationName = "") {
    const expected = normalizeRibbonParameterPresetSessionState(state);
    if (expected === "idle") return ribbonParameterPresetSessionState === "idle";
    if (ribbonParameterPresetSessionState !== expected) return false;
    const name = String(animationName || "").trim();
    return !name || !ribbonParameterPresetSessionAnimationName || ribbonParameterPresetSessionAnimationName === name;
  }

  function isRibbonParameterPresetSessionActive(animationName = "") {
    if (ribbonParameterPresetSessionState === "idle") return false;
    const name = String(animationName || "").trim();
    return !name || !ribbonParameterPresetSessionAnimationName || ribbonParameterPresetSessionAnimationName === name;
  }

  function getRibbonParameterPresetSessionPanel() {
    return Array.from(document.querySelectorAll('[data-novaflow-ribbon-panel="1"], .nf-panel')).find((panel) => (
      panel instanceof HTMLElement && isRibbonAccordionPanel(panel)
    )) || null;
  }

  function getRibbonParameterPresetSessionAnimationName() {
    try {
      return getRibbonReactProjectContext()?.animationName || "";
    } catch (_) {
      return "";
    }
  }

