  function hasRibbonAdvancedBodyContent(card, button) {
    if (!(card instanceof HTMLElement)) return false;
    return Array.from(card.children).some((child) => {
      if (!(child instanceof HTMLElement) || child === button) return false;
      if (child.querySelector(".nf-slider, input[type='range']")) return true;
      const text = normalizeText(child.textContent || "");
      if (!text) return false;
      return Object.values(RIBBON_PARAMETER_SLIDER_LABELS).some((label) => text.includes(normalizeText(label))) ||
        text.includes(normalizeText(RIBBON_ELASTICITY_SLIDER_LABEL)) ||
        text.includes(normalizeText(RIBBON_SWING_COUNT_SLIDER_LABEL)) ||
        text.includes(normalizeText(RIBBON_SWING_COUNT_LEGACY_SLIDER_LABEL)) ||
        text.includes(normalizeText(RIBBON_WHIP_STRENGTH_SLIDER_LABEL));
    });
  }

