      '[data-novaflow-ai-storyboard-history="1"] > div > div[style*="overflow: hidden"]:not([style*="position: fixed"]):not([data-novaflow-ai-history-positioned="1"]) button, ' +
      '[data-novaflow-ai-storyboard-history="1"] > div > div[style*="overflow: hidden"]:not([style*="position: fixed"]):not([data-novaflow-ai-history-positioned="1"]) [role="button"], ' +
      '[data-novaflow-ai-storyboard-history="1"] > div > div[style*="overflow:hidden"]:not([style*="position:fixed"]):not([data-novaflow-ai-history-positioned="1"]) button, ' +
      '[data-novaflow-ai-storyboard-history="1"] > div > div[style*="overflow:hidden"]:not([style*="position:fixed"]):not([data-novaflow-ai-history-positioned="1"]) [role="button"]'
