        group.style.setProperty("row-gap", `${SPRITE_EDITOR_SLIDER_TITLE_GAP}px`, "important");
        group.style.setProperty("height", `${SPRITE_EDITOR_SLIDER_GROUP_HEIGHT}px`, "important");
