        row.style.setProperty("height", `${SPRITE_EDITOR_SLIDER_ROW_HEIGHT}px`, "important");
        row.style.setProperty("min-height", `${SPRITE_EDITOR_SLIDER_ROW_HEIGHT}px`, "important");
        row.style.setProperty("max-height", `${SPRITE_EDITOR_SLIDER_ROW_HEIGHT}px`, "important");
        row.style.setProperty("gap", `${SPRITE_EDITOR_SLIDER_ROW_GAP}px`, "important");
        row.style.setProperty("column-gap", `${SPRITE_EDITOR_SLIDER_ROW_GAP}px`, "important");
