        row.style.setProperty("min-width", `${SPRITE_EDITOR_SLIDER_ROW_WIDTH}px`, "important");
        row.style.setProperty("max-width", `${SPRITE_EDITOR_SLIDER_ROW_WIDTH}px`, "important");
        row.style.setProperty("box-sizing", "border-box", "important");
