  function renderArtGeneratePromptHistoryPopover() {
    if (window.NovaFlowUiDesignDrawing?.isActive?.()) {
      closeArtGeneratePromptHistoryPopover(false);
      return;
    }
    const key = ART_GENERATE_STATE.promptHistoryOpenKey;
    if (key !== "prompt" && key !== "negativePrompt") {
      document.getElementById(ART_GENERATE_PROMPT_HISTORY_POPOVER_ID)?.remove();
      return;
    }
    let popover = document.getElementById(ART_GENERATE_PROMPT_HISTORY_POPOVER_ID);
    if (!(popover instanceof HTMLElement)) {
      popover = document.createElement("div");
      popover.id = ART_GENERATE_PROMPT_HISTORY_POPOVER_ID;
      popover.setAttribute("data-novaflow-runtime-ignore", "1");
      document.body?.appendChild(popover);
    }
    popover.setAttribute("data-novaflow-runtime-ignore", "1");
    bindArtGeneratePromptHistorySurfaceEvents(popover);
    popover.className = "novaflow-art-generate-history-popover";
    const rect = ART_GENERATE_STATE.promptHistoryPopupRect || { left: 10, top: 80, width: 420 };
    Object.assign(popover.style, {
      left: `${Math.max(0, Math.round(Number(rect.left) || 0))}px`,
      top: `${Math.max(0, Math.round(Number(rect.top) || 0))}px`,
      width: `${Math.max(320, Math.round(Number(rect.width) || 420))}px`,
      height: `${Math.max(52, Math.round(Number(rect.height) || getArtGeneratePromptHistoryPopoverEstimatedHeight(key)))}px`
    });
    popover.innerHTML = "";
    const rows = buildArtGeneratePromptHistoryPopoverEntries(key).map((entry) => (
      renderArtGeneratePromptHistoryPopoverRow(key, entry.item, entry.options)
    ));
    if (!rows.filter(Boolean).length) rows.push(createArtEl("div", { className: "novaflow-art-generate-history-popover-empty", text: "\u6682\u65e0" }));
    popover.appendChild(createArtEl("div", { className: "novaflow-art-generate-history-popover-list" }, rows));
  }

  function focusArtGeneratePromptTextareaNode(textarea) {
    if (!(textarea instanceof HTMLTextAreaElement) || textarea.disabled || textarea.readOnly) return;
    if (document.activeElement === textarea) return;
    try {
      textarea.focus({ preventScroll: true });
    } catch {
      textarea.focus();
    }
  }

  function focusArtGeneratePromptTextarea(event) {
    const textarea = event?.currentTarget;
    if (!(textarea instanceof HTMLTextAreaElement)) return;
    if (event && typeof event.stopPropagation === "function") event.stopPropagation();
    focusArtGeneratePromptTextareaNode(textarea);
    if (event?.type === "pointerdown" || event?.type === "mousedown" || event?.type === "click") {
      window.setTimeout(() => focusArtGeneratePromptTextareaNode(textarea), 0);
    }
  }

  function getArtGeneratePromptTextareaFromEvent(event) {
    const target = event?.target instanceof Element ? event.target : null;
    const textarea = target?.closest?.(`#${ART_GENERATE_WORKSPACE_ID} .novaflow-art-generate-prompt textarea`);
    return textarea instanceof HTMLTextAreaElement ? textarea : null;
  }

  function handleArtGeneratePromptTextareaFocusGuard(event) {
    if (!ART_GENERATE_STATE.active) return;
    const textarea = getArtGeneratePromptTextareaFromEvent(event);
    if (!(textarea instanceof HTMLTextAreaElement)) return;
    focusArtGeneratePromptTextareaNode(textarea);
    window.setTimeout(() => focusArtGeneratePromptTextareaNode(textarea), 0);
  }

  function bindArtGeneratePromptTextareaFocusGuard() {
    if (window.__NovaFlowArtGeneratePromptTextareaFocusGuardBound) return;
    window.__NovaFlowArtGeneratePromptTextareaFocusGuardBound = true;
    ["pointerdown", "mousedown", "click"].forEach((eventName) => {
      window.addEventListener(eventName, handleArtGeneratePromptTextareaFocusGuard, { capture: true });
    });
  }

